//MobileAssistiveSystemTouch.js - Hex to MobileConfig installer for Shadowrocket
// Version: 1.0

// ====================================================
// PHẦN 1: DỮ LIỆU HEX CỦA BẠN
// ====================================================
var hexData = 
"";

// ====================================================
// PHẦN 2: HÀM GIẢI MÃ HEX
// ====================================================
function hexToBytes(hex) {
    var bytes = [];
    for (var i = 0; i < hex.length; i += 2) {
        bytes.push(parseInt(hex.substr(i, 2), 16));
    }
    return bytes;
}

function bytesToBase64(bytes) {
    var binary = '';
    for (var i = 0; i < bytes.length; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

// ====================================================
// PHẦN 3: HÀM CÀI MOBILECONFIG (CHO SHADOWROCKET)
// ====================================================
function installMobileConfig() {
    // Chuyển hex → bytes → base64
    var bytes = hexToBytes(hexData);
    var base64Data = bytesToBase64(bytes);
    
    // Tạo mobileconfig từ base64
    var mobileconfig = atob(base64Data);
    
    // Gửi request đến Shadowrocket để cài profile
    $httpClient.post({
        url: "http://127.0.0.1:6156/install-profile",
        body: mobileconfig,
        headers: {
            "Content-Type": "application/x-apple-aspen-config"
        }
    }, function(error, response, data) {
        if (error) {
            console.log("❌ Cài profile thất bại: " + error);
        } else {
            console.log("✅ Cài profile thành công!");
            console.log("📱 Vào Settings → General → VPN & Device Management để xác nhận");
        }
    });
}

// ====================================================
// PHẦN 4: TỰ ĐỘNG CHẠY KHI LOAD SCRIPT
// ====================================================
console.log("🔧 Đang cài đặt MobileConfig tối ưu máy...");
installMobileConfig();

// Export cho Shadowrocket
$done();
